// Check and handle ground collision (bottom boundary)
if (p->position.y < h) {
    p->position.y = -p->position.y + 2 * h + BOX_COLLISION_OFFSET;
    p->velocity.y = -p->velocity.y * elasticity;
}

// Check and handle left wall collision
if (p->position.x < -boxWidth) {
    p->position.x = -p->position.x + 2 * boxWidth + BOX_COLLISION_OFFSET;
    p->velocity.x = -p->velocity.x * elasticity;
}

// Check and handle right wall collision
if (p->position.x > boxWidth) {
    p->position.x = -p->position.x + 2 * boxWidth - BOX_COLLISION_OFFSET;
    p->velocity.x = -p->velocity.x * elasticity;
}

// Check and handle front wall collision
if (p->position.z < -boxWidth) {
    p->position.z = -p->position.z + 2 * boxWidth + BOX_COLLISION_OFFSET;
    p->velocity.z = -p->velocity.z * elasticity;
}

// Check and handle back wall collision
if (p->position.z > boxWidth) {
    p->position.z = -p->position.z + 2 * boxWidth - BOX_COLLISION_OFFSET;
    p->velocity.z = -p->velocity.z * elasticity;
}

